# Child Development and Pedagogy (REET Level 1, Part I): development, individual
# differences, intelligence and personality, learning theories, motivation,
# learners with special needs, assessment, action research and the RTE Act 2009.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "Development: Erikson", "According to Erikson, a toddler of about 1 to 3 years who is encouraged to do things alone develops a sense of",
      ["autonomy", "initiative", "industry", "identity"],
      "Erikson's second stage is autonomy versus shame and doubt (about 1 to 3 years). Initiative versus guilt follows in the preschool years and industry versus inferiority in the school years."),
    S(1, 2, "Learning: Skinner", "Skinner developed the idea of operant conditioning mainly from experiments with",
      ["rats and pigeons in a box", "dogs and a ringing bell", "chimpanzees and sticks", "cats in a puzzle box"],
      "Skinner's box let rats press levers and pigeons peck keys for food. The bell and dogs are Pavlov, the sticks Kohler and the puzzle box Thorndike."),
    S(1, 2, "Learning: Pavlov", "In Pavlov's experiment, the food that makes a dog salivate without any learning is the",
      ["unconditioned stimulus", "conditioned stimulus", "conditioned response", "neutral stimulus"],
      "Food produces salivation naturally, so it is the unconditioned stimulus. The bell starts as a neutral stimulus and becomes the conditioned stimulus after pairing."),
    S(1, 2, "Learning: Kohler", "Kohler, who studied insight learning in chimpanzees, belonged to which school of psychology?",
      ["Gestalt", "Behaviourism", "Psychoanalysis", "Functionalism"],
      "Kohler was a Gestalt psychologist: he held that learners grasp the whole pattern of a problem. Behaviourists such as Thorndike and Skinner explained learning through stimulus and response."),
    S(1, 2, "Assessment: bias", "A teacher gives a well-behaved child high marks for weak answers because she likes the child. This error is the",
      ["halo effect", "Hawthorne effect", "placebo effect", "recency effect"],
      "The halo effect is letting one good impression (behaviour, neatness) colour the judgement of something else. Clear marking criteria reduce it."),
    S(1, 3, "Intelligence: IQ", "A child has a mental age of 9 years and a chronological age of 12 years. What is the child's IQ?",
      ["75", "90", "108", "133"],
      "IQ = mental age / chronological age x 100 = 9 / 12 x 100 = 75. Dividing the other way, 12 / 9 x 100, gives the wrong answer 133."),
    S(1, 2, "Motivation: Maslow", "In Maslow's hierarchy, which needs come just above physiological needs?",
      ["Safety needs", "Esteem needs", "Belonging needs", "Self-actualisation"],
      "The order from the base is physiological, safety, love and belonging, esteem, then self-actualisation. A child who feels unsafe at home or school finds it hard to learn."),
    S(1, 2, "Intelligence: theories", "Thurstone described intelligence as made up of",
      ["seven primary mental abilities", "one general factor and specific factors", "eight separate intelligences", "fluid and crystallised abilities"],
      "Thurstone's primary mental abilities include verbal meaning, number, space, memory and reasoning. A general factor with specific factors is Spearman, eight intelligences is Gardner and fluid and crystallised is Cattell."),
    S(1, 2, "Learners with special needs", "A Class 4 girl speaks well and understands lessons, but her letters are badly formed and her spacing is uneven. She most likely has",
      ["dysgraphia", "dyslexia", "dyscalculia", "aphasia"],
      "Dysgraphia is a difficulty with writing by hand: forming letters, spacing and writing on the line. Dyslexia affects reading and dyscalculia affects number."),
    S(1, 1, "Individual differences", "Children in one class learn at different speeds and in different ways. A teacher should",
      ["vary her methods and pace for them", "give everyone the same worksheet daily", "teach only to the fastest learners", "seat children by their last marks"],
      "Individual differences call for varied methods, materials and pace so every child can learn. One worksheet for all, or teaching to toppers, leaves many children behind."),
    S(1, 2, "Assessment", "At the end of a lesson, a teacher asks three quick questions to decide what to reteach tomorrow. This is",
      ["formative assessment", "summative assessment", "an entrance test", "a board examination"],
      "Assessment during teaching that is used to adjust the next lesson is formative. Summative assessment sums up learning at the end of a term or year."),
    S(1, 1, "RTE Act 2009", "The Right of Children to Free and Compulsory Education Act, 2009 applies to children aged",
      ["6 to 14 years", "3 to 6 years", "5 to 15 years", "6 to 18 years"],
      "The RTE Act gives every child from 6 to 14 years the right to free and compulsory elementary education (Classes 1 to 8) in a neighbourhood school."),
    S(1, 2, "Sociometry", "A teacher asks each child to name two classmates they would like to work with and draws the choices as a chart of arrows. This chart is",
      ["a sociogram", "a rating scale", "an anecdotal record", "a cumulative record"],
      "A sociogram maps the choices children make about one another. It shows popular children, mutual pairs and children nobody chose, who may need help to join in."),
    S(1, 3, "Heredity and environment", "Studies of identical twins raised in different homes are useful because they help to",
      ["separate the effects of genes and home", "prove that heredity decides everything", "show that twins learn more slowly", "measure the twins' height accurately"],
      "Identical twins share the same genes, so differences between twins raised apart point to the environment, and similarities point to heredity."),
    S(1, 2, "Adjustment: defence mechanisms", "Not chosen for the school team, Raju says, 'I never wanted to play anyway.' This defence mechanism is",
      ["rationalisation", "projection", "regression", "reaction formation"],
      "Rationalisation gives an acceptable reason to cover a disappointment (sour grapes). Projection would blame others for one's own faults, and regression is going back to childish behaviour."),
    # ---------- Practice Test 2 ----------
    S(2, 1, "Development: Piaget", "When her mother steps out of the room, a nine-month-old crawls to the door to look for her. Piaget would say the baby now has",
      ["object permanence", "conservation", "reversibility", "abstract reasoning"],
      "The baby knows her mother still exists when out of sight, which is object permanence, the key achievement of the sensorimotor stage (birth to about 2 years)."),
    S(2, 2, "Development: Piaget", "A five-year-old says the wind is alive because it moves the trees. Piaget called this belief",
      ["animism", "centration", "reversibility", "seriation"],
      "Animism, giving life and feelings to non-living things, is typical of the preoperational stage. Centration is focusing on one feature of a problem at a time."),
    S(2, 2, "Learning: Skinner", "A boy who snatches classmates' crayons is not allowed on the swing that day, and he snatches less afterwards. Losing the swing is",
      ["punishment", "negative reinforcement", "positive reinforcement", "extinction"],
      "Taking away something pleasant (swing time) to reduce a behaviour is (negative) punishment. Negative reinforcement removes something unpleasant to increase a behaviour, which is the usual confusion."),
    S(2, 2, "Adjustment: defence mechanisms", "After her baby brother is born, a six-year-old starts sucking her thumb again. This defence mechanism is",
      ["regression", "projection", "rationalisation", "sublimation"],
      "Going back to the behaviour of an earlier age under stress is regression. Sublimation turns an urge into an acceptable activity, such as anger into sport."),
    S(2, 2, "Intelligence: Gardner", "A child who understands her own feelings and strengths well shows which of Gardner's intelligences?",
      ["Intrapersonal", "Interpersonal", "Naturalist", "Linguistic"],
      "Intrapersonal intelligence is knowing oneself. Interpersonal intelligence is understanding other people, which is often confused with it."),
    S(2, 3, "Intelligence: Guilford", "Guilford's Structure of Intellect model classifies intellectual abilities along which three dimensions?",
      ["Operations, contents and products", "Verbal, numerical and spatial", "Fluid, crystallised and general", "Analytical, creative and practical"],
      "Guilford described every ability as an operation (such as divergent or convergent production) applied to a content to give a product. Fluid and crystallised are Cattell's terms and analytical, creative and practical are Sternberg's."),
    S(2, 2, "Development: Kohlberg", "In Kohlberg's theory, a person who follows universal principles of justice even against a law is at the",
      ["post-conventional level", "pre-conventional level", "conventional level", "concrete operational level"],
      "At the post-conventional level, morality rests on principles such as justice and rights. At the conventional level, people follow rules and laws to keep order and approval."),
    S(2, 2, "Memory", "Children remember the colours of the rainbow in order through the made-up word VIBGYOR. Such a memory aid is called a",
      ["mnemonic", "reflex", "conditioned response", "projective device"],
      "A mnemonic links new material to an easy pattern, such as a word built from first letters, so it can be recalled in order. It works best alongside understanding, not in place of it."),
    S(2, 2, "Learning: practice", "Revising in short sessions spread over several days, rather than in one long session, is called",
      ["distributed practice", "massed practice", "overlearning", "rote learning"],
      "Spaced or distributed practice gives better long-term memory than massed practice (cramming), because each session refreshes memory before it fades."),
    S(2, 3, "Transfer of learning", "Judd's theory says that learning transfers to new situations mainly through",
      ["understanding general principles", "identical elements in both tasks", "training the mind like a muscle", "repeating a task many times"],
      "Judd's generalisation theory: a principle understood in one setting can be applied in another. Identical elements is Thorndike's theory and training the mind like a muscle is formal discipline."),
    S(2, 2, "Assessment tools", "A teacher wants to know how each child feels about mathematics. The most suitable tool is",
      ["an attitude scale", "an achievement test", "a speed test", "an intelligence test"],
      "An attitude scale asks how strongly a child agrees with statements such as 'I enjoy maths', so it measures feelings. An achievement test measures what has been learned."),
    S(2, 2, "Learners with special needs", "Which approach helps a slow learner most in a regular class?",
      ["Extra time and concrete examples", "Moving the child to a lower class", "Giving the child no homework at all", "Comparing the child with toppers"],
      "Slow learners need more time, smaller steps, concrete materials and frequent revision. Comparison and demotion damage confidence without helping learning."),
    S(2, 2, "RTE Act 2009", "At the time of admission, the RTE Act, 2009 forbids schools from",
      ["screening the child or the parents", "asking the child's name and age", "giving the child a school uniform", "recording the parents' address"],
      "Section 13 bans any screening procedure for admission and any capitation fee. Recording a child's details is ordinary admission work."),
    S(2, 2, "Teacher expectations", "A teacher believes some children are bright, and they do better because she expects more of them. This is the",
      ["Pygmalion effect", "halo effect", "Hawthorne effect", "placebo effect"],
      "When a teacher's expectations shape how she treats children, and so how they perform, it is the Pygmalion (or Rosenthal) effect. It is a reason to expect a lot of every child."),
    S(2, 2, "Personality", "Carl Jung divided personality into which two types?",
      ["Introvert and extrovert", "Id and superego", "Oral and anal", "Endomorph and ectomorph"],
      "Jung described introverts, turned towards their inner world, and extroverts, turned towards people and activity. Id and superego are Freud's terms; endomorph and ectomorph are Sheldon's body types."),
    # ---------- Drill only ----------
    S(0, 2, "Personality: Freud", "In Freud's theory, the part of personality that works on the pleasure principle is the",
      ["id", "ego", "superego", "persona"],
      "The id seeks immediate pleasure. The ego works on the reality principle and the superego is the conscience."),
    S(0, 2, "Personality tests", "The Rorschach inkblot test is an example of a",
      ["projective test", "group intelligence test", "achievement test", "aptitude test"],
      "In a projective test, a person reads meaning into an unclear picture and so reveals inner feelings. The Thematic Apperception Test is another projective test."),
    S(0, 2, "Assessment: objectives", "Which learning objective belongs to the affective domain?",
      ["Shows interest in caring for plants", "Names the parts of a flowering plant", "Draws a neat diagram of a leaf", "Measures the height of a seedling"],
      "The affective domain covers feelings, interests and values. Naming parts is cognitive, and drawing or measuring are mainly skills."),
    S(0, 2, "Educational thinkers", "'Emile', a book arguing that education should follow the child's own nature, was written by",
      ["Rousseau", "Dewey", "Froebel", "Gandhi"],
      "Jean-Jacques Rousseau's Emile (1762) argued that children learn best from nature and experience, an idea that shaped child-centred education."),
    S(0, 1, "Educational thinkers", "Who founded the school at Shantiniketan, where children learnt in the open, close to nature?",
      ["Rabindranath Tagore", "Mahatma Gandhi", "Swami Vivekananda", "Sri Aurobindo"],
      "Tagore started his school at Shantiniketan in 1901 with classes under the trees; it later grew into Visva-Bharati."),
    S(0, 2, "Assessment", "A test that checks whether each child can do a stated skill, without comparing children, is",
      ["criterion-referenced", "norm-referenced", "standardised for age", "a speed test"],
      "A criterion-referenced test compares each child with a fixed standard. A norm-referenced test compares a child with other children."),
    S(0, 2, "Assessment", "A test that gives nearly the same scores when given again to the same children is",
      ["reliable", "valid", "objective", "diagnostic"],
      "Reliability is consistency of scores. Validity is whether the test measures what it claims to measure; a test can be reliable but not valid."),
    S(0, 2, "Learners with special needs", "A Class 3 child with attention deficit hyperactivity disorder (ADHD) struggles through long lessons. Which step helps her most?",
      ["Short tasks with movement breaks", "A seat at the back, out of the way", "Longer written work to calm her", "Punishment each time she gets up"],
      "Children with ADHD learn better with work broken into short, clear tasks, regular chances to move and a seat near the teacher, away from distractions. Punishment and long tasks make focus harder."),
]
